/**
 * Merges two dictionaries (objects).
 *
 * @param {Object} obj1 - The first dictionary.
 * @param {Object} obj2 - The second dictionary.
 *
 * @returns {Object} A new dictionary containing all properties from both objects.
 */
function mergeDictionaries(obj1, obj2) {
  const merged = { ...obj1 };

  for (const key in obj2) {
    if (obj2.hasOwnProperty(key)) {
      merged[key] = obj2[key];
    }
  }

  return merged;
}
